select b.board_id, b.board_title, b.board_content, b.category_idx, b.view_count, b.notice_yn, b.reg_date, b.member_id, m.role, COALESCE(m.member_name, '알 수 없음') as member_name, (select count(*) from comment c where c.board_id = b.board_id and c.del_yn = 'N') as comment_cnt from board b left join member m on b.member_id = m.member_id
and category_idx = #{category}
order by b.reg_date desc limit #{start}, #{count}

